import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getQuestionById, postQuestion } from '../../services/api';
import './EditQuestionForm.css';

function EditQuestionForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(true);
  const [tags, setTags] = useState('');


  useEffect(() => {
    getQuestionById(id).then(question => {
      setTitle(question.title);
      setText(question.text);
      if(question.tags)
      { setTags(question.tags.map(tag=> tag.name).join(', ')); }
      setLoading(false);
    });
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const updatedQuestion = {
        id: Number(id),
        title,
        text,
        user: { id: Number(localStorage.getItem('userId')) }
      };

      const response = await fetch(`http://localhost:8080/questions/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
        body: JSON.stringify(updatedQuestion),
      });

      const result = await response.text();
      alert(result);
      navigate(`/questions/${id}`);
    } catch (err) {
      alert('Eroare la actualizare întrebare: ' + err.message);
    }
  };

  if (loading) return <p>Se încarcă formularul...</p>;

  return (
    <form onSubmit={handleSubmit} className="edit-question-form">
      <h2>Editează întrebarea</h2>
      <input
        type="text"
        value={title}
        onChange={e => setTitle(e.target.value)}
        required
        placeholder="Titlul întrebării"
      />
      <textarea
        value={text}
        onChange={e => setText(e.target.value)}
        required
        placeholder="Conținutul întrebării"
      />
       <input
          type="text"
          value={tags}
          onChange={e => setTags(e.target.value)}
          placeholder="Etichete (ex: java, spring)"
       />



      <button type="submit">Salvează modificările</button>
    </form>
  );
}

export default EditQuestionForm;
